-- ===== 본문 재추출 반영 2/2 (parse800.py 생성) =====
-- 러닝헤더가 끼어든 본문/뒤바뀐 본문을 PDF에서 다시 추출한 값으로 교체. id·코스·진도는 그대로.
-- 이 파일 16행 / 전체 86행

UPDATE public.words SET meaning = '전략적 상황에 처한 경제주체들의 행동을 분석하는데 유용하게 활용되는 게임이론의 한 예로서, 협력적인 선택이 양자에게 최선임에도 불구하고 자신의 이익에 치중한 선택으로 인해 오히려 두 사람 모두에게', detailed_meaning = '전략적 상황에 처한 경제주체들의 행동을 분석하는데 유용하게 활용되는 게임이론의 한 예로서, 협력적인 선택이 양자에게 최선임에도 불구하고 자신의 이익에 치중한 선택으로 인해 오히려 두 사람 모두에게 바람직하지 않은 결과를 가져오는 상황을 말한다. 죄수의 딜레마(Prisoners’ Dilemma)는 1950년 미국 프린스턴대 터커(A. Tucker) 교수가 게임 이론을 설명하기 위해 이용한 다음의 예화에서 비롯되었다. 경찰이 두 용의자 Ⅰ, Ⅱ를 격리하여 심문하면서 자백을 이끌어 내려고 다음과 같이 말하였다고 가정한다. ① 한 사람이 자백하고 다른 사람은 입을 다물었다면 자백한 사람은 1단위의 보상, 입을 다문 사람은 2단위의 벌금형이 부과된다. ② 두 사람이 모두 자백하면 각각에게는 1단위의 벌금형이 부과된다. ③ 두 사람이 모두 자백하지 않으면 Ⅰ과 Ⅱ는 혐의가 없다. 이러한 상황에서 두 사람이 직면하는 보상행렬은 아래와 같아지는데, Ⅰ과 Ⅱ는 모두 상대방의 전략과 상관없이 자백하는 전략을 선택하게 되므로 결과적으로 두 사람이 서로를 믿고 자백하지 않는 전략을 취할 때보다 나쁜 결과에 직면하게 된다. 용의자 Ⅱ 구분자백함 자백하지 않음 자백함 (-1, -1) (1, -2) 용의자 Ⅰ자백하지 않음 (-2, 1) (0, 0) 즉 개인적인 수준에서는 합리적인 선택이 구성원 전체로 보아서는 비합리적인 선택이 되는 결과를 가져오는 딜레마를 낳게 되는데, 이 같은 죄수의 딜레마 문제는 광고경쟁, 기업의 환경오염, 국가간 군비경쟁 등 다양한 상황에 적용될 수 있다.', related_words = ARRAY['치킨게임']::text[] WHERE id = 521;  -- 죄수의 딜레마
UPDATE public.words SET meaning = '주가연계증권(ELS; Equity Linked Security)은 개별 주식의 가격이나 특정 주가지수의 변동에 연계되어 특정조건 충족시 약정된 투자손익이 결정되는 금융투자상품이다.', detailed_meaning = '주가연계증권(ELS; Equity Linked Security)은 개별 주식의 가격이나 특정 주가지수의 변동에 연계되어 특정조건 충족시 약정된 투자손익이 결정되는 금융투자상품이다. 주가 연계증권 발행 증권사는 발행대금의 상당부분을 채권, 예금 등 안전자산에 투자하는 한편나머지를 주식, 주식관련 파생상품 등에 투자하여 약정수익 재원 확보를 위한 초과수익을 추구한다. 주가연계증권은 만기, 수익구조 등을 다양하게 설계할 수 있는 장점이 있으나 유가증권시장에 상장되지 않음에 따라 유동성이 낮고 발행증권사의 신용리스크에 노출되는 단점이 있다. 대신 기초자산이 일정수준 이상인 경우 자동 조기상환되는 조건이 부여되어 있으며 5~10%의 환매수수료를 부담하는 조건으로 발행증권사에 환매를 요구할수 있다. 한편 증권회사가 발행하는 주가연계증권과 유사한 상품으로는 자산운용사가 운용하는 주가연계펀드(ELF; Equity Linked Fund)와 은행이 취급하는 주가연계예금(ELD; Equity Linked Deposit) 등이 있다. 주가연계증권은 1980년대 후반 미국, 홍콩 등에서 판매되기 시작하였으며, 우리나라에서는 2003년 2월 판매가 허용되었다. 발행방식은 공모보다 사모가 많은 편이며 투자자는 개인 및 일반법인이 절반 이상을 차지하는 가운데자산운용사, 퇴직연금, 신탁 등도 투자하고 있다.', related_words = '{}'::text[] WHERE id = 523;  -- 주가연계증권(ELS)
UPDATE public.words SET meaning = '주가지수옵션(Stock Index Options)은 주가지수(기초자산)를 만기일에 사전에 약정한 가격(행사가격)으로 매입하거나 매도할 수 있는 권리를 거래하는 파생금융상품으로서 매입권리인', detailed_meaning = '주가지수옵션(Stock Index Options)은 주가지수(기초자산)를 만기일에 사전에 약정한 가격(행사가격)으로 매입하거나 매도할 수 있는 권리를 거래하는 파생금융상품으로서 매입권리인 콜옵션(call option)과 매도권리인 풋옵션(put option)으로 구분된다. 옵션의 매도자는 매수자에게 옵션을 제공하고 매수자는 그 대가로 프리미엄(옵션가격)을 지급한다. 콜옵션 매수자는 만기일에 기초자산가격(코스피200 종가 등)이 행사가격을 넘어서 면 권리를 행사할 유인이 발생하며, 기초자산가격이 행사가격에 프리미엄을 더한 값을 초과하는 금액만큼 매수자의 이익(매도자의 손실)이 된다. 풋옵션 매수자는 만기일에 기초자산가격(코스피200 종가 등)이 행사가격보다 낮아야만 권리를 행사할 유인이 발생하며, 기초자산가격이 행사가격에서 프리미엄을 차감한 값을 하회하는 금액만큼 풋옵션 매수자의 이익(매도자의 손실)이 된다. 주가지수옵션은 주가지수선물과 마찬가지로 실물이 존재하지 않는 주가지수를 대상으로 하고 있으나 거래의 목적물이 권리라는 점에서 주가지수선물과 다르다. 또한 주가지수옵션은 주가지수선물과 달리 기초자산 가격변동에 따른 손익구조가 비대칭적이다. 옵션매수자는 손실이 프리미엄으로 한정되는 반면 이익은 기초자산가격에 비례하여 증가하고, 역으로 옵션매도자는 이익이 프리미엄에 국한되는 반면손실은 제한이 없다. 주가지수옵션시장은 1983년 3월 미국의 시카고옵션거래소(CBOE; Chicago Board Options Exchange)에서 S&P100지수를 대상으로 최초로 개설되었으며 우리나라에서는 1997년 7월에 코스피200 옵션시장이, 2001년 11월에 코스닥50 옵션시장이 개설되었다.', related_words = ARRAY['주가지수선물거래']::text[] WHERE id = 526;  -- 주가지수옵션
UPDATE public.words SET meaning = '주택저당증권(MBS; Mortgage-Backed Securities)이란 자산유동화증권(ABS)의 일종으로써 모기지(또는 주택담보대출)를 기초자산으로 발행되는 증권이다.', detailed_meaning = '주택저당증권(MBS; Mortgage-Backed Securities)이란 자산유동화증권(ABS)의 일종으로써 모기지(또는 주택담보대출)를 기초자산으로 발행되는 증권이다. 원래 주택저당증권은 미국에서 제2차 세계대전 이후 참전한 군인들의 주거 안정을 위해 도입된 제도 인데 우리나라에서는 IMF 외환위기 이후 본격적으로 취급되기 시작하였다. MBS시장은 세 종류의 시장으로 구분되는데 1차 시장은 모기지 차입자와 모기지 대출기관 사이에 모기지론이 이루어지는 시장이며, 2차 시장은 모기지 대출기관이 보유하고 있는 모기지를 유동화(증권화)하는 시장이며 자본시장은 모기지가 유동화된 주택저당증권이 투자자에 게 매각되고 유통되는 시장을 말한다. 주택저당증권은 일반 채권과는 다른 특징을 보유하고 있다. 보통 채권은 발행자가 원리금 상환을 부담하는데 반해 MBS는 통상 기초자산을 특수목적회사(SPC)에 이전하고 SPC가 발행하는 것이기 때문에 원리금 상환이 발행자의 신용에 기초하기보다는 기초자산의 현금 흐름에 의존하게 된다. 또한 MBS에는 조기상환위험(prepayment risk)이라는 독특한 위험이 존재한다. 시장금리가 하락하는 경우에는 기존 모기지 차입자가 이자비용 절감을 위해 동 모기지를 조기에 상환하고 금리가 더 낮은 모기지론을 받게 되는데 모기지 상환이 이루어지면 그것을 기초자산으로 하고 있는 MBS도 조기에 상환이 이루어지게 된다. 이것을 투자자 입장에서 보면 자산 듀레이션이 당초 예상보다 줄어들어 국채 추가 매입 등 자산 듀레이션을 더 늘려야 하는 문제(반대로 시장금리가 상승하는 경우에는 자산 듀레이션이 당초 예상보다 늘어나 보유채권 매각 등 자산 듀레이션을 줄여야 하는 문제)를 야기한다. 그래서 투자자는 MBS를 투자할 때는 적정 조기상환율을 산정하고 이를 토대로 투자를 하게 된다. 은행이 보유하고 있는 모기지를 유동화하는 경우 모기지론에서 발생하는 이자수익은 줄어들지만 매각대금으로 모기지를 추가로 취급할 수 있는 여력이 생기며 위험자산이 줄어들기 때문에 BIS비율이 올라가는 긍정적인 효과를 기대할 수 있다. 현재 우리나라에서는 은행이 모기지론을 취급하며 한국주택금융공사가 동 모기지를 유동화하여 자본시장에 매각하는 형태로 이루어지고 있다.', related_words = ARRAY['자산유동화','모기지대출']::text[] WHERE id = 530;  -- 주택저당증권(MBS)
UPDATE public.words SET meaning = '중앙거래당사자(CCP; Central Counterparty)는 증권거래 계약의 매도자에 대해 매수자역할을, 매수자에 대해서는 매도자 역할을 수행하는 기관으로서 다자간 차감에 의한 청산업무를', detailed_meaning = '중앙거래당사자(CCP; Central Counterparty)는 증권거래 계약의 매도자에 대해 매수자역할을, 매수자에 대해서는 매도자 역할을 수행하는 기관으로서 다자간 차감에 의한 청산업무를 수행하여 결제 유동성을 절약하는 한편 결제이행보증 서비스를 제공하여 참가자의 리스크관리 부담을 경감시키고 신용 및 유동성리스크를 집중하여 관리하는 역할을 수행하고 있다. 한편 글로벌 금융위기 이후 모든 표준화된 장외파생상품거래의 중앙거래당사자를 통한 청산이 의무화됨에 따라 결제리스크가 집중되는 중앙거래당사자에 대한 리스크 관리의 중요성이 더욱 커지고 있다. 우리나라의 장내 증권 및 파생상품 거래는 한국거래소가 중앙거래당사자 역할을 수행하고 있다. 장외거래의 경우 금융위원회로부터 금융투자상품거래청산업 인가를 받은 한국거래소와 한국예탁결제원이 각각 장외파생상품거래(원화 이자율스왑거래)와 주식기관투자자거래(상장주식의 위탁매매거래)에 대해 중앙거래당사자의 역할을 하고 있다.', related_words = ARRAY['지급결제시스템']::text[] WHERE id = 534;  -- 중앙거래당사자
UPDATE public.words SET meaning = '증권 현물을 거래할 경우 또는 선물/옵션을 거래할 경우에 매매당사자 일방 또는 매매당사자 쌍방이 매매약정을 이행한다는 증거로 중개회사에 예치하는 금액을 말한다.', detailed_meaning = '증권 현물을 거래할 경우 또는 선물/옵션을 거래할 경우에 매매당사자 일방 또는 매매당사자 쌍방이 매매약정을 이행한다는 증거로 중개회사에 예치하는 금액을 말한다. 주식 현물매수 주문시 사고자 하는 주식 매입금액의 일정비율에 해당하는 금액을 증거금으로 미리 예치해야 하며 나머지 대금은 매수가 이루어진 후 실제 결제일에 납부한다. 선물거래에서도 가격변동에 따른 계약불이행을 방지하기 위해 담보적 성격의 증거금을 납부한다. 선물거래에서 증거금을 납부함으로써 가격 하락시에는 매수자의 계약불이행 가능성으로 부터 매도자를 보호하고 가격 상승시에는 매도자의 계약불이행 가능성으로부터 매수자를 보호할 수 있다. 증거금에는 고객이 중개회사에 납부하는 위탁증거금과 중개회사가 고객으로부터 받은 증거금 중 일부를 결제기관에 납부하는 매매증거금이 있다.', related_words = ARRAY['증권결제리스크']::text[] WHERE id = 538;  -- 증거금
UPDATE public.words SET meaning = '중앙은행이 금융기관으로 하여금 예금 등과 같은 채무의 일정비율에 해당하는 금액을 중앙은행에 예치하도록 하는 제도이다.', detailed_meaning = '중앙은행이 금융기관으로 하여금 예금 등과 같은 채무의 일정비율에 해당하는 금액을 중앙은행에 예치하도록 하는 제도이다. 은행이 예금고객의 지급요구에 응하기 위해 미리 준비해 놓은 유동성 자산을 지급준비금이라 하고, 적립대상 채무 대비 지급준비금의 비율을 지급준비율이라 한다. 지급준비금은 은행이 중앙은행에 예치하고 있는 자금(지준예치금) 과 보유하고 있는 현금(시재금)으로 구성된다. 지급준비제도(Reserve Requirement)는 1863년 미국에서 예금자보호를 위해 법정지급준비금을 부과한 것이 효시라 할 수 있다. 그 후 1930년대 들어 지급준비율을 변경하여 본원통화를 조절하면 승수효과를 통해 통화량에 영향을 준다는 사실이 밝혀지면서 지급준비제도는 중앙은행의 유동성조절수단으로 그 위상이 높아졌다. 그러나 1980년대 이후 금융의 자유화 및 개방화 등으로 시장기능에 바탕을 둔 통화정책의 필요성이 부각되면서 공개시장운영이 주된 통화정책 수단으로 부각된 가운데 지급준비제도는 여러 한계점으로 인해 정책수단으로서의 역할이 상대적으로 축소되었다. 그러나 중앙은행은 지급준비율 변경을 통해 금융기관의 자금사정을 변화시키고 시중유동성을 조절할 수 있으며 나아가 금융안정을 도모하고 금융시장에 중앙은행의 정책방향을 강력하게 알리는 공시효과가 있기 때문에 지급준비제도는 여전히 유용한 정책수단으로 활용되고 있다.', related_words = ARRAY['통화정책수단']::text[] WHERE id = 550;  -- 지급준비제도
UPDATE public.words SET meaning = '지분형 모기지는 정부나 공공기관이 주택의 일부를 지분으로 투자함으로써 주택 구매자의 자금 부담을 완화해 주는 주택금융 제도이다.', detailed_meaning = '지분형 모기지는 정부나 공공기관이 주택의 일부를 지분으로 투자함으로써 주택 구매자의 자금 부담을 완화해 주는 주택금융 제도이다. 동 제도를 이용할 경우 매수자는 자기자본과 일부 대출만으로 집을 마련할 수 있고, 나머지는 공공기관이 지분을 보유하는 방식으로 부담을 나누게 된다. 예를 들어 10억 원짜리 주택을 구매할 때, 매수자가 1억 원의 자기자본과 4억 원의 대출을 마련하면, 나머지 5억 원은 공공기관이 지분 투자로 참여하게 된다. 이때 등기부에는 공동명의로 등록되며, 매수자는 공공기관의 지분에 대해 낮은 수준의 사용료를 지불한다. 집값이 상승하면 매각 시 시세차익은 지분율에 따라 나뉘고, 하락 시에는 공공기관이 손실을 먼저 부담하는 구조로 위험 분산 효과도 기대할 수 있다. 또한 매수자는 추후 여유 자금이 생기면 공공 지분을 추가로 매입해 완전한 소유권을 확보할 수도 있다. 동 제도는 청년층과 무주택자의 내 집 마련을 돕고, 가계부채 증가 를 억제하는 정책적 목적도 함께 갖고 있다. 다만 동 제도의 운용에 관한 구체적인 사항은 2025년 7월 현재 확정되지 않았다.', related_words = ARRAY['주택금융제도','한국주택금융공사']::text[] WHERE id = 554;  -- 지분형 모기지
UPDATE public.words SET meaning = '지주회사는 다른 회사의 주식을 소유하여 그 회사의 사업내용을 지배하는 것을 주된 사업으로 하는 회사이다.', detailed_meaning = '지주회사는 다른 회사의 주식을 소유하여 그 회사의 사업내용을 지배하는 것을 주된 사업으로 하는 회사이다. 공정거래법에서는 다른 회사의 사업내용을 지배할 목적으로 소유하는 주식의 대차대조표상 장부가액의 합계액이 당해 회사 자산총액의 50% 이상인 회사를 지주회사로 규정하고 있다. 지주회사는 지주회사가 사업을 영위하는가의 여부에 따라 순수지주회사와 사업지주회사로 구분된다. 순수지주회사는 다른 기업의 사업내용 지배만을 목적으로 하는 지주회사를 말하고 사업지주회사는 자기사업을 영위하면서 다른 기업의 사업내용을 지배하는 지주회사를 말한다.', related_words = ARRAY['M&A']::text[] WHERE id = 559;  -- 지주회사
UPDATE public.words SET meaning = '진성어음(Commercial Bill)이란 기업간 상거래에 있어 대금결제를 위해 발행되는 어음 으로 상업어음, 물품대금어음(물대어음)이라고도 한다.', detailed_meaning = '진성어음(Commercial Bill)이란 기업간 상거래에 있어 대금결제를 위해 발행되는 어음 으로 상업어음, 물품대금어음(물대어음)이라고도 한다. 진성어음을 받은 납품업체는 약정된 날짜에 현금을 받을 수 있으나 원활한 자금순환을 위해 금융기관에서 미리 할인받아 현금화하는 것이 일반적이다. 진성어음은 상거래를 수반할 때만 발행할 수 있다는 점에서 순수하게 자금을 조달할 목적으로 발행되는 융통어음(Accommodation Bill)과는 구별된다. 진성어음과 융통어음은 모두 약속어음의 일종으로 외견상 구분할 수 있는 기준은 없다. 다만 금융기관은 진성어음을 할인하는 과정에서 어음 뒷면에 납품기업의 세금계산서를 첨부하도록 요구해 진성어음임을 확인한다. 융통어음 중에서도 신용상태가 양호한 기업이 운전자금 등 단기자금을 조달하기 위해 자기신용(대부분 신용평가기관의 신용평가 필요)을 바탕으로 발행하여 단기금융시장에서 유통되는 어음을 기업어음(CP; Commercial Paper)이라고 한다.', related_words = ARRAY['기업어음(CP)']::text[] WHERE id = 563;  -- 진성어음/융통어음
UPDATE public.words SET meaning = '기업에서는 지속적인 생산능력을 유지하고 경쟁력을 확보하기 위해 노후설비를 새로운설비로 대체하거나 신규 사업 진출을 위해 공장도 짓고 기계도 구매하는데 이러한 경제활동은 해당연도의 이익만을 위한', detailed_meaning = '기업에서는 지속적인 생산능력을 유지하고 경쟁력을 확보하기 위해 노후설비를 새로운설비로 대체하거나 신규 사업 진출을 위해 공장도 짓고 기계도 구매하는데 이러한 경제활동은 해당연도의 이익만을 위한 것이 아니고 미래의 지속적인 수입의 보장 등 장기적인안목에서 이루어진다. 이렇게 장기간에 걸쳐 생산과정에 반복적, 지속적으로 사용되는 유형 또는 무형의 산출물을 고정자산이라 하고, 생산주체에 의한 고정자산의 순취득(취득- 처분)을 총고정자본형성(GFCF; gross fixed capital formation)이라 한다. 총고정자본형성에는 토지나 중고품의 구매는 제외되고 고정자산 취득에 따른 설치비용이나 취득세, 등록세 등의 부대비용은 포함된다.', related_words = ARRAY['총투자율']::text[] WHERE id = 576;  -- 총고정자본형성
UPDATE public.words SET meaning = '통화신용정책보고서는 한국은행이 통화신용정책 결정 내용과 배경, 향후 통화정책방향등을 종합적으로 정리해 국회에 정기적으로 제출하는 법정 보고서로, 한국은행법 제96조에 따라 연 2회 작성하고 있다.', detailed_meaning = '통화신용정책보고서는 한국은행이 통화신용정책 결정 내용과 배경, 향후 통화정책방향등을 종합적으로 정리해 국회에 정기적으로 제출하는 법정 보고서로, 한국은행법 제96조에 따라 연 2회 작성하고 있다. 동 보고서는 통화정책의 투명성과 책임성, 예측 가능성을 높이기 위한 핵심 수단으로 활용된다. 동 보고서는 국내외 경제 상황, 물가 흐름, 금융·외환시장 동향 등을 분석하여 통화정책 결정의 배경을 설명한다. 또한 기준금리 결정의 근거와 그에 따른 정책 기조, 금융중개지원대출 등 유동성 공급 수단의 운용 현황, 향후 정책 방향에 대한 전망과 함께 서술 대상 기간의 주요 경제 현안에 대한 심층 분석도 포함하고 있다. 통화신용정책보고서는 단순한 정책 결과 보고를 넘어, 한국은행이 경제를 어떻게 진단하고 어떤 철학과 전략으로 대응하고 있는지를 보여주는 중요한 정책 커뮤니케이 션 수단이다. 각 경제주체들은 통화신용정책보고서를 통해 한국은행의 통화신용정책 운영 상황을 보다 잘 이해하고, 향후 정책방향에 대해 합리적인 기대를 형성해 나갈 수 있다. 보고서는 한국은행 홈페이지에서 누구나 열람할 수 있으며, 주요 내용은 기자설명회및 동영상 등을 통해서도 공유된다.', related_words = '{}'::text[] WHERE id = 613;  -- 통화신용정책보고서
UPDATE public.words SET meaning = '중앙은행은 통화정책을 수행함에 있어 정책수단과 최종목표(물가안정, 금융안정 등)를 이 어줄 수 있는 다양한 지표를 활용하는 것이 일반적이다.', detailed_meaning = '중앙은행은 통화정책을 수행함에 있어 정책수단과 최종목표(물가안정, 금융안정 등)를 이 어줄 수 있는 다양한 지표를 활용하는 것이 일반적이다. 우선 중앙은행은 통화정책의 최종목표와 밀접한 관계가 있는 통화량, 환율, 물가상승률 등의 지표 중에 하나를 선택하여그 지표의 목표 수준을 결정한 다음, 이를 달성할 수 있도록 통화정책을 수행한다. 이렇게선택된 지표를 명목기준지표(nominal anchor)라고 하며 이중 물가상승률을 제외한 통화량, 환율 등은 최종목표를 달성하기 위한 중간목표(intermediate target)로 활용된다. 그러나 통화량, 환율 등도 중앙은행이 직접 제어할 수 있는 지표가 아니다. 따라서 중앙은 행이 다른 변수의 영향을 받지 않고 직접 제어하여 원하는 수준을 유지할 수 있는 지표가 필요한데 이를 운용목표(operating target)라고 하며 일반적으로 단기시장금리나 지급준비금이 사용된다. 중앙은행은 이러한 운용목표의 적정 수준을 설정하고 공개시장운영, 중앙은행 여수신제도, 지급준비제도 등의 정책수단(policy tool)을 활용하여 동 수준을 유지함으로써 궁극적으로 최종목표를 달성하기 위해 노력한다. 한편 통화정책의 결정과 집행에는 이를 뒷받침할 수 있는 제도가 필요한데 의사결정 및 집행기구, 외부압력으로부터의 독립성 확보장치, 정책수행 결과에 대한 책임성 제고방안, 그리고 통화정책의 신뢰성과 유효성 확보를 위한 투명성 증대 장치 등이 이에 포함된다. 이와 같은 최종목표, 명목기준지표, 운용목표, 정책수단, 의사결정 관련 제도 등을 모두 포괄하여 통화정책체계라고 한다.', related_words = ARRAY['통화정책 운영체제(monetary policy regime)']::text[] WHERE id = 621;  -- 통화정책체계 (Monetary Policy Framework)
UPDATE public.words SET meaning = '한계비용은 재화나 서비스를 한 단위 더 생산하는데 들어가는 비용의 증가분을 의미한 다.', detailed_meaning = '한계비용은 재화나 서비스를 한 단위 더 생산하는데 들어가는 비용의 증가분을 의미한 다. 즉 비용증가분을 생산증가분으로 나눈 값이다. 예를 들면, 생수 100병을 생산하는 데 10,000원의 비용이 소요된다면 생수 1병의 평균생산비용은 100원이다. 추가로 생수한 병을 더 생산하여 101병, 102병을 생산할 때 비용이 각각 10,080원, 10,150원이라면 생수 101병째의 한계비용은 10,080원 ­10,000원 = 80원, 102병째의 한계비용은 70 원이 된다. 생산의 경제성을 분석하는 데에 있어 비용이 얼마나 소요되는가도(10,080원→10,150원) 중요하지만 생산을 늘림에 따라 증가하는 추가적 비용이 어떻게 변하는가를 (80원→70원) 살피는 것도 매우 중요하다. 왜냐하면 생산의 목적이 이윤을 극대화하는 데있다면 반드시 한계비용의 움직임을 살펴보아야 판단할 수 있기 때문이다. 이는 수학적으로 어떤 함수값(총비용)의 최소는 변수(생산규모)의 미분값이 0이 되는 곳에서 결정되는 데, 한계의 개념은 바로 미분과 일맥상통한다는 것을 상기하면 이해될 수 있다. 일반적으로 생산이 증가하면서 한계비용은 점차 줄어들다가 어느 생산규모에 이르면 다시 늘어나 기 시작한다.', related_words = ARRAY['수확체감의 법칙','한계효용']::text[] WHERE id = 643;  -- 한계비용
UPDATE public.words SET meaning = '현용화폐는 현재 대한민국에서 법적으로 통용되고 있는 공식적인 지급수단으로서, 한국은행이 독점 발행권을 가지고 있는 은행권(지폐)과 주화(동전)를 의미한다.', detailed_meaning = '현용화폐는 현재 대한민국에서 법적으로 통용되고 있는 공식적인 지급수단으로서, 한국은행이 독점 발행권을 가지고 있는 은행권(지폐)과 주화(동전)를 의미한다. 한국은행법 제47조 및 제53조에 따르면, 한국은행은 은행권과 주화의 발행권을 독점적으로 보유하고 있으며, 이들 화폐는 대한민국 영토 내에서 무제한으로 법적 통용력을 가진다. 즉, 상거래및 채권·채무관계에서 금액의 제한 없이 지급수단으로 사용할 수 있다. 현용화폐는 법화로서, 모든 거래에서 유효한 지급수단으로 인정되며, 이를 통해 거래가 이루어지면 채권· 채무관계가 종결된 것으로 간주된다. 현재 우리나라에서 사용되는 현용화폐는 1962년 제 2차 통화조치 이후에 발행된 화폐 중 유통이 정지되지 않은 화폐들을 의미한다. 구체적으로 은행권은 오만원권, 만원권, 오천원권, 천원권의 4종류가 있으며, 주화는 오백원화, 백원화, 오십원화, 십원화, 오원화, 일원화의 6종류가 현용주화로 통용되고 있다. 한국은행은 화폐의 발행뿐 아니라, 화폐의 도안, 액면, 크기, 소재 등 기본적 사항을 금융통화위원회가 정부의 승인을 받아 결정하도록 하고 있으며 화폐는 한국조폐공사가 제조하여 한국은행에 인계하면, 한국은행이 이를 금융기관에 공급함으로써 시중에 유통된다. 아울러 현용화폐는 위조 방지를 위한 다양한 장치와 함께 국민 편의를 위한 디자인 및 규격 변화를 거쳐 왔으며, 한국은행은 화폐의 안정적인 공급과 효율적인 관리를 통해 현용화폐가 원활히 유통될 수 있도록 노력하고 있다.', related_words = ARRAY['미발행화폐','실물화폐/명목화폐']::text[] WHERE id = 655;  -- 현용화폐
UPDATE public.words SET meaning = '환전영업자는 외국통화의 매입·매도 또는 외국에서 발행한 여행자수표의 매입을 업으로 영위하는 자를 말한다.', detailed_meaning = '환전영업자는 외국통화의 매입·매도 또는 외국에서 발행한 여행자수표의 매입을 업으로 영위하는 자를 말한다. 매입할 수 있는 대상은 외국통화와 여행자수표에 한하며 외화송금수표 환어음 등은 매입할 수 없다. 환전영업자는 원칙적으로 외환매입만 가능하고 외환매도는 지정거래외국환은행을 통해서만 가능하다. 다만, 2015년 1월부터 2천 달러(동일자ㆍ동일인 기준) 이하 금액은 비거주자뿐만 아니라 거주자에게도 매도할 수 있게 되었다. 환전영업자가 2천 달러 초과 금액을 지정거래외국환은행이 아닌 자에게 매도할 경우에는 비거주자에 대해서만 가능하며, 재환전 금액까지만 매도할 수 있다. 환전영업은 1999년 4월부터 인가제에서 등록제로 전환되었는데, 이에 따라 필요한 시설을 갖춘 자는 누구든지(개인 포함) 관세청장에게 등록하면 환전영업에 종사할 수 있다. 환전영업자가 환전을 할 때에는 금액과 관계없이 주민등록증, 여권, 사업자등록증, 납세번호증 등 실명확인증표를 통해 상대방의 인적사항을 확인하여야 한다.', related_words = '{}'::text[] WHERE id = 671;  -- 환전영업자(환전상)

NOTIFY pgrst, 'reload schema';
